(function(){"use strict";
const API="/api",TOKEN="cs360_portal_aprovador_token",labels={viagem:"Viagem",mobilidade:"Mobilidade",entregas:"Entregas",estacionamento:"Estacionamento",correios:"Correios",xerox:"Xerox / Impressões",achados_perdidos:"Achados e Perdidos",liberacao_acesso:"Acessos",autorizacao_excepcional:"Autorizações Excepcionais",transporte:"Transporte",solicitacao_imagens:"Imagens"};
let pending=[],history=[],selected=null,urgentOnly=false;
const $=id=>document.getElementById(id),esc=value=>String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char])),parseDate=value=>new Date(String(value).replace(" ","T")),formatDate=value=>{const date=parseDate(value);return isNaN(date)?"—":new Intl.DateTimeFormat("pt-BR",{dateStyle:"short",timeStyle:"short"}).format(date)},formatMoney=value=>`R$ ${Number(value).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2})}`;
async function api(path,options={}){const response=await fetch(API+path,{...options,headers:{"Content-Type":"application/json",...(localStorage.getItem(TOKEN)?{Authorization:`Bearer ${localStorage.getItem(TOKEN)}`}:{})}}),body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error?.message||"Falha na API");return body}
async function auth(){const login=await api("/auth/login",{method:"POST",body:JSON.stringify({email:"gestor.demo@hospital-demo.org"})});localStorage.setItem(TOKEN,login.data.token)}
function deadline(item){const start=parseDate(item.createdAt),hours=item.urgent?24:72;return new Date(start.getTime()+hours*36e5)}
function deadlineInfo(item){const diff=deadline(item)-Date.now(),hours=Math.ceil(Math.abs(diff)/36e5);if(diff<0){const days=Math.max(1,Math.ceil(hours/24));return {label:`Atrasada há ${days} ${days===1?"dia":"dias"}`,urgent:true,score:deadline(item).getTime()}}if(hours<=24)return {label:hours<=3?`${hours}h restantes`:"Vence hoje",urgent:true,score:deadline(item).getTime()};const days=Math.ceil(hours/24);return {label:`${days} ${days===1?"dia restante":"dias restantes"}`,urgent:false,score:deadline(item).getTime()}}
function value(value,required=false){if(value!==undefined&&value!==null&&String(value).trim()!=="")return {text:String(value),missing:false};return required?{text:"Informação necessária para decisão",missing:true}:{text:"Não se aplica",missing:false}}
function specificData(item){const d=item.details||{};switch(item.serviceType){case"viagem":return [["Origem",d.origin,true],["Destino",d.destination,true],["Ida",d.departureDate,true],["Volta",d.returnDate,true],["Motivo",d.reason,true],["Custo estimado",d.estimatedCost?formatMoney(d.estimatedCost):null,true]];case"mobilidade":return [["Tipo de solicitação",d.actionType||d.provider,true],["Finalidade",d.reason,true],["Centro de custo",item.costCenter,true],["Período",d.period||d.periodFrom,false]];case"entregas":return [["Origem",d.origin,true],["Destino",d.destination,true],["Volume / peso",d.weight||d.volume||d.itemDescription,false],["Finalidade",d.reason||d.itemDescription,true]];case"estacionamento":return [["Tipo",d.requestType,true],["Veículo",[d.vehicleModel,d.vehiclePlate].filter(Boolean).join(" "),true],["Período",[d.periodStart,d.periodEnd].filter(Boolean).join(" → "),true],["Unidade",d.location,true]];case"liberacao_acesso":return [["Tipo de acesso",d.accessType||d.journey,true],["Recurso / local",d.resource,true],["Período",d.period,true],["Justificativa",d.justification,true]];default:return [["Descrição",d.description||d.content||d.details||item.title,true],["Justificativa",d.justification||d.reason,false],["Custo / impacto",d.estimatedCost?formatMoney(d.estimatedCost):null,false]]}}
function normalizedFields(item){return specificData(item).map(([label,raw,required])=>({label,...value(raw,required)}))}
function summary(item){return `<b>${esc(item.id)}</b><span>${esc(labels[item.serviceType]||item.serviceType)}</span><span>${esc(item.requesterName)}</span>`}
function compactRoute(item){const d=item.details||{};if(item.serviceType==="viagem")return `${esc(d.origin||"—")} → ${esc(d.destination||"—")}<small>${esc(d.departureDate||"—")} → ${esc(d.returnDate||"—")}</small>`;if(item.serviceType==="entregas")return `${esc(d.origin||"—")} → ${esc(d.destination||"—")}<small>${esc(d.itemDescription||d.weight||"Volume não especificado")}</small>`;if(item.serviceType==="estacionamento")return `${esc(d.requestType||"Estacionamento")}<small>${esc([d.vehicleModel,d.vehiclePlate].filter(Boolean).join(" ")||"Veículo não informado")}</small>`;if(item.serviceType==="liberacao_acesso")return `${esc(d.accessType||d.journey||"Acesso")}<small>${esc(d.resource||"Recurso não informado")}</small>`;return `${esc(d.reason||d.description||item.title)}<small>${esc(d.period||d.city||"")}</small>`}
function approvalCard(item){const due=deadlineInfo(item),fields=normalizedFields(item),blocked=fields.some(field=>field.missing),cost=item.details?.estimatedCost?`${formatMoney(item.details.estimatedCost)} <small>estimado</small>`:"Não se aplica";return `<article class="manager-card" data-id="${esc(item.id)}"><div class="manager-card-top"><div><span class="service-label">${esc(labels[item.serviceType]||item.serviceType)}</span><b>${esc(item.id)}</b></div><span class="deadline-badge ${due.urgent?"urgent":""}">${esc(due.label)}</span></div><h3>${esc(item.title)}</h3><div class="requester-line"><strong>${esc(item.requesterName)}</strong><span>${esc(item.details?.department||"Área Demonstrativa")} · ${esc(item.costCenter)}</span></div><div class="decision-facts"><div class="route-fact">${compactRoute(item)}</div><div><small>Custo / impacto</small><strong>${cost}</strong></div></div>${blocked?'<p class="missing-warning">Informação necessária para decisão. Consulte os detalhes.</p>':""}<div class="manager-actions"><button class="btn secondary" data-detail="${item.id}">Ver detalhes</button><button class="btn primary" data-approve="${item.id}" ${blocked?"disabled title=\"Complete as informações obrigatórias\"":""}>Aprovar</button><button class="btn danger" data-reject="${item.id}">Rejeitar</button></div></article>`}
function filteredPending(){const query=$("approval-search").value.toLowerCase(),service=$("approval-service").value,urgency=$("approval-urgency").value;return [...pending].filter(item=>(!query||`${item.id} ${item.requesterName} ${labels[item.serviceType]||item.serviceType}`.toLowerCase().includes(query))&&(!service||item.serviceType===service)&&(!urgency||(urgency==="urgent")===deadlineInfo(item).urgent)&&(urgentOnly?deadlineInfo(item).urgent:true)).sort((a,b)=>deadlineInfo(a).score-deadlineInfo(b).score)}
function renderPending(){const items=filteredPending();$("approvals").innerHTML=items.length?items.map(approvalCard).join(""):'<div class="empty">Nenhuma decisão encontrada para estes filtros.</div>';bindActions()}
function renderHistory(){$("history-list").innerHTML=history.length?history.slice().sort((a,b)=>parseDate(b.updatedAt)-parseDate(a.updatedAt)).slice(0,8).map(item=>`<button class="history-row" data-history-detail="${item.id}"><b>${esc(item.id)}</b><span>${esc(labels[item.serviceType]||item.serviceType)}<small>${esc(item.title)}</small></span><span>${esc(item.requesterName)}</span><span class="decision-badge ${item.status.toLowerCase()}">${item.status==="APROVADO"?"Aprovado":"Rejeitado"}</span><time>${formatDate(item.updatedAt)}</time><span>Gestor Demo</span><i>→</i></button>`).join(""):'<div class="empty">Sem decisões registradas nesta alçada.</div>';document.querySelectorAll("[data-history-detail]").forEach(button=>button.onclick=()=>openDetail(button.dataset.historyDetail))}
async function load(){const [pendingResult,historyResult]=await Promise.all([api("/approvals/my-pending"),api("/approvals/history")]);pending=pendingResult.data;history=historyResult.data;$("pending").textContent=pending.length;$("count").textContent=`${pending.length} pendentes`;$("due").textContent=pending.filter(item=>deadlineInfo(item).urgent).length;$("history-count").textContent=history.length;const types=[...new Set(pending.map(item=>item.serviceType))];$("approval-service").innerHTML='<option value="">Todos os serviços</option>'+types.map(type=>`<option value="${type}">${esc(labels[type]||type)}</option>`).join("");renderPending();renderHistory()}
async function openDetail(id){try{selected=(await api(`/approvals/${encodeURIComponent(id)}`)).data;const fields=normalizedFields(selected),due=deadlineInfo(selected),policy='<div class="policy-safe"><b>Política aplicável</b><p>Não há política institucional vigente cadastrada para esta solicitação.</p><small>A decisão pode ser registrada, mas não há referência normativa disponível no protótipo para apoiar a análise.</small></div>';$("detail-title").textContent=`${selected.id} · ${selected.title}`;$("detail-body").innerHTML=`<div class="detail-meta"><span class="service-label">${esc(labels[selected.serviceType]||selected.serviceType)}</span><span class="badge">${esc(selected.status)}</span><span class="deadline-badge ${due.urgent?"urgent":""}">${esc(due.label)}</span></div><section><h3>Solicitante</h3><div class="detail-grid"><div><small>Nome</small><b>${esc(selected.requesterName)}</b></div><div><small>Área</small><b>${esc(selected.details?.department)}</b></div><div><small>Centro de custo</small><b>${esc(selected.costCenter)}</b></div><div><small>Perfil</small><b>EmployeeProfile demonstrativo</b></div></div></section><section><h3>Dados específicos</h3><div class="detail-grid">${fields.map(field=>`<div class="${field.missing?"missing":""}"><small>${esc(field.label)}</small><b>${esc(field.text)}</b></div>`).join("")}</div></section><section><h3>Por que esta solicitação veio para você?</h3><p>${esc(selected.approvalReason||"Solicitação submetida à sua alçada demonstrativa.")}</p></section>${policy}<section><h3>Histórico</h3><div class="timeline">${(selected.history||[]).map(event=>`<div><b>${esc(event.action)}</b><br><small>${esc(event.date)} · ${esc(event.user)}</small></div>`).join("")}</div></section><section class="attachments"><h3>Anexos</h3><p>Nenhum anexo demonstrativo disponível.</p></section>`;$("detail-actions").innerHTML=selected.status==="PENDENTE_APROVACAO"?`<button class="btn complement" disabled title="Feature flag demonstrativa; state machine ainda não suporta complemento">Solicitar complemento · em estudo</button><button class="btn danger" data-reject="${selected.id}">Rejeitar</button><button class="btn primary" data-approve="${selected.id}" ${fields.some(field=>field.missing)?"disabled":""}>Aprovar</button>`:"<button class=\"btn secondary\" data-close=\"detail-overlay\">Fechar</button>";openOverlay("detail-overlay");setAssistant(selected);bindActions()}catch(error){toast(error.message)}}
function openDecision(id,action){selected=pending.find(item=>item.id===id)||selected;if(!selected)return;$(action==="approve"?"approve-summary":"reject-summary").innerHTML=summary(selected);if(action==="approve"){$("approve-comment").value="";openOverlay("approve-overlay")}else{$("reject-reason").value="";$("reject-error").hidden=true;openOverlay("reject-overlay")}}
async function decide(action){if(!selected)return;const body=action==="approve"?{comment:$("approve-comment").value.trim()}:{reason:$("reject-reason").value.trim()};if(action==="reject"&&!body.reason){$("reject-error").hidden=false;$("reject-reason").focus();return}const button=$(action==="approve"?"confirm-approve":"confirm-reject");button.disabled=true;try{await api(`/approvals/${encodeURIComponent(selected.id)}/${action}`,{method:"POST",body:JSON.stringify(body)});closeOverlays();toast(action==="approve"?"Solicitação aprovada.":"Solicitação rejeitada.");selected=null;await load()}catch(error){toast(error.message)}finally{button.disabled=false}}
function bindActions(){document.querySelectorAll("[data-detail]").forEach(button=>button.onclick=()=>openDetail(button.dataset.detail));document.querySelectorAll("[data-approve]").forEach(button=>button.onclick=()=>openDecision(button.dataset.approve,"approve"));document.querySelectorAll("[data-reject]").forEach(button=>button.onclick=()=>openDecision(button.dataset.reject,"reject"));document.querySelectorAll("[data-close]").forEach(button=>button.onclick=()=>closeOverlay(button.dataset.close))}
function openOverlay(id){$(id).hidden=false;document.body.classList.add("overlay-open")}function closeOverlay(id){$(id).hidden=true;if(!document.querySelector(".approver-overlay:not([hidden])"))document.body.classList.remove("overlay-open")}function closeOverlays(){document.querySelectorAll(".approver-overlay").forEach(overlay=>overlay.hidden=true);document.body.classList.remove("overlay-open")}
function setAssistant(item=null){const assistant=$("assistant");assistant.dataset.role="GESTOR_APROVADOR";assistant.dataset.currentPage="portal-aprovador";assistant.dataset.currentRequest=item?.id||"";assistant.dataset.currentService=item?.serviceType||"";assistant.dataset.applicablePolicies=JSON.stringify(item?.applicablePolicy?[item.applicablePolicy]:[]);$("assistant-context").textContent=item?`${item.id} · ${labels[item.serviceType]||item.serviceType}`:"Portal do Gestor/Aprovador"}
function toast(text){const element=document.createElement("div");element.className="toast";element.textContent=text;document.body.append(element);setTimeout(()=>element.remove(),2600)}
$("theme").onclick=()=>{const theme=document.documentElement.dataset.theme==="dark"?"light":"dark";document.documentElement.dataset.theme=theme;localStorage.setItem("cs360_theme",theme)};$("history-nav").onclick=$("history-stat").onclick=()=>$("history").scrollIntoView({behavior:"smooth"});$("approvals-nav").onclick=$("pending-stat").onclick=()=>{urgentOnly=false;$("approval-urgency").value="";renderPending();$("pending-section").scrollIntoView({behavior:"smooth"})};$("due-stat").onclick=()=>{urgentOnly=true;$("approval-urgency").value="urgent";renderPending();$("pending-section").scrollIntoView({behavior:"smooth"})};["approval-search","approval-service","approval-urgency"].forEach(id=>$(id).addEventListener(id==="approval-search"?"input":"change",()=>{urgentOnly=false;renderPending()}));$("assistant-open").onclick=()=>{$("assistant").hidden=false;setAssistant(selected)};$("assistant-close").onclick=()=>$("assistant").hidden=true;$("confirm-approve").onclick=()=>decide("approve");$("confirm-reject").onclick=()=>decide("reject");document.querySelectorAll(".quick-reasons button").forEach(button=>button.onclick=()=>{$("reject-reason").value=button.textContent==="Outro"?"":button.textContent;$("reject-reason").focus()});document.querySelectorAll(".approver-overlay").forEach(overlay=>overlay.onclick=event=>{if(event.target===overlay)closeOverlay(overlay.id)});document.onkeydown=event=>{if(event.key==="Escape"){closeOverlays();$("assistant").hidden=true}};
document.documentElement.dataset.theme=localStorage.getItem("cs360_theme")||"dark";setAssistant();(async()=>{try{await auth();await load()}catch(error){toast(error.message);$("approvals").innerHTML='<div class="empty">Não foi possível carregar sua alçada.</div>'}})();
})();
